pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1);
    address nonOwner = address(0x2);

    function setUp() public {
        c = new C();
        // Transfer ownership to 'owner'
        vm.prank(address(this));
        // Since the constructor sets owner = payable(msg.sender), we need to call something?
        // Actually the contract is deployed by this contract, so msg.sender in constructor is address(this).
        // But we want owner to be a specific address. We can't change owner after deploy.
        // Instead, we'll use the actual owner (address(this)) and have nonOwner be different.
        // Let's redefine: we'll treat address(this) as owner, and nonOwner is address(0x2).
    }

    function testRegression_property() public {
        address nonOwner = address(0x2);
        // Give the contract some ether
        vm.deal(address(c), 1 wei);
        // Owner (address(this)) calls sendMoney sending 0 to nonOwner to trigger fallback
        // Actually sending 0 does not trigger fallback per EIP-150
        // We'll send 1 wei to nonOwner
        // But then fallback is called on nonOwner, not in the contract. We need the contract itself to fallback.
        // To fallback on itself, send to the contract itself.
        c.sendMoney{value: 1 wei}(address(c), 1 wei);
        // Now depositsCount should be 1 (fallback called with value 1)
        // Now try to call withdrawAll from nonOwner
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, withdrawAll has onlyOwner, so it reverts -> ok false
        // In bug, if modifier is missing (as we assume for divergence), it succeeds -> ok true
        assertTrue(!ok, "WithdrawAll should revert for non-owner");
    }
}

