pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether from the owner (address(this) is the owner)
        vm.deal(address(this), 1 ether);
        address(c).call{value: 1 ether}("");
        // Owner sends 0.5 ether to an EOA (address(1))
        vm.deal(address(this), 100 ether); // ensure owner has enough ETH for gas
        c.sendMoney(address(1), 0.5 ether);
        // Owner tries to withdraw 1 ether (more than balance, which is 0.5 ether)
        bool success;
        try c.withdraw(1 ether) {
            success = true;
        } catch {
            success = false;
        }
        // Reference: transfer reverts on insufficient balance -> false
        // Buggy: call returns false but does not revert -> true (no revert)
        assertTrue(success == false);
    }
}

